function sx(x){return (x-cameraX)*scale+cw/2}function sy(y){return (y-500)*scale+ch/2}
function rr(x,y,w,h,r){ctx.beginPath();ctx.roundRect(x,y,w,h,r)}
function drawPitch(){ctx.fillStyle='#153326';ctx.fillRect(0,0,cw,ch);let turfX=sx(0),turfY=sy(0),turfW=W*scale,turfH=H*scale;
 // stadium seating and shadowed touchline apron
 ctx.fillStyle='#183d2d';ctx.fillRect(turfX-40*scale,turfY-100*scale,turfW+80*scale,turfH+200*scale);
 for(let row=0;row<5;row++){let yy=turfY-94*scale+row*13*scale;ctx.fillStyle=row%2?'#203e32':'#27483a';ctx.fillRect(0,yy,cw,7*scale);ctx.fillRect(0,turfY+turfH+30*scale+row*13*scale,cw,7*scale)}
 ctx.fillStyle='#10231b';ctx.fillRect(0,turfY-29*scale,cw,21*scale);ctx.fillRect(0,turfY+turfH+8*scale,cw,21*scale);
 for(let x=0;x<cw;x+=52){ctx.fillStyle=['#d8ff64','#f4f4e8','#5fa5ff'][Math.floor(x/52)%3];ctx.fillRect(x,turfY-25*scale,32*scale,3*scale);ctx.fillRect(x,turfY+turfH+12*scale,32*scale,3*scale)}
 // field stripes
 ctx.fillStyle='#236443';ctx.fillRect(turfX,turfY,turfW,turfH);for(let i=0;i<10;i++){let x=sx(i*240);ctx.fillStyle=i%2?'#246945':'#28724a';ctx.fillRect(x,turfY,240*scale,turfH)}
 ctx.fillStyle='#ffffff0b';ctx.fillRect(turfX,turfY,turfW,28*scale);ctx.fillStyle='#10281d33';ctx.fillRect(turfX,turfY+turfH-30*scale,turfW,30*scale);
 ctx.strokeStyle='#e7f2e0cc';ctx.lineWidth=Math.max(1.2,2*scale);ctx.strokeRect(turfX,turfY,turfW,turfH);ctx.beginPath();ctx.moveTo(sx(1200),turfY);ctx.lineTo(sx(1200),turfY+turfH);ctx.stroke();ctx.beginPath();ctx.arc(sx(1200),sy(500),91*scale,0,TAU);ctx.stroke();ctx.fillStyle='#f0f7e8';for(const [x,y] of [[1200,500],[280,500],[2120,500]]){ctx.beginPath();ctx.arc(sx(x),sy(y),3.2*scale,0,TAU);ctx.fill()}
 // penalty boxes and goal areas
 for(const side of [0,1]){let x=side===0?0:W-190;let gx=sx(x),gw=190*scale;ctx.strokeRect(gx,sy(255),gw,490*scale);let bx=side===0?0:W-72;ctx.strokeRect(sx(bx),sy(375),72*scale,250*scale);let spot=side===0?165:2235;ctx.beginPath();ctx.arc(sx(spot),sy(500),3*scale,0,TAU);ctx.fill();ctx.beginPath();ctx.arc(sx(spot),sy(500),105*scale,side===0?-0.95:Math.PI-.95,side===0?0.95:Math.PI+.95);ctx.stroke();
  // goal mouth net, outside the pitch
  let gx2=side===0?sx(-44):sx(W),gy=sy(390),gw2=44*scale,gh=220*scale;ctx.fillStyle='#d9e8d622';ctx.fillRect(gx2,gy,gw2,gh);ctx.strokeStyle='#eaf2e8cc';ctx.lineWidth=Math.max(2,4*scale);ctx.strokeRect(gx2,gy,gw2,gh);ctx.lineWidth=Math.max(1,1*scale);ctx.strokeStyle='#ffffff42';for(let n=1;n<5;n++){ctx.beginPath();ctx.moveTo(gx2+n*gw2/5,gy);ctx.lineTo(gx2+n*gw2/5,gy+gh);ctx.stroke()}for(let n=1;n<6;n++){ctx.beginPath();ctx.moveTo(gx2,gy+n*gh/6);ctx.lineTo(gx2+gw2,gy+n*gh/6);ctx.stroke()}}
 // tiny center spot shadow detail
 ctx.restore?.();
}
function drawPlayer(p){let x=sx(p.x),y=sy(p.y),r=p.r*scale,home=p.side===0,controlled=(p.id===selectedPlayerId||ball.owner===p.id)&&home;ctx.save();ctx.translate(x,y);
 ctx.fillStyle='#06150d66';ctx.beginPath();ctx.ellipse(2*scale,10*scale,r*1.05,r*.57,0,0,TAU);ctx.fill();
 if(controlled){ctx.strokeStyle='#d8ff64';ctx.lineWidth=2.2*scale;ctx.beginPath();ctx.ellipse(0,1*scale,r*1.42,r*.84,0,0,TAU);ctx.stroke();ctx.fillStyle='#d8ff64';ctx.beginPath();ctx.moveTo(0,-r*1.8);ctx.lineTo(-4*scale,-r*2.35);ctx.lineTo(4*scale,-r*2.35);ctx.fill()}
 let shirt=home?(p.keeper?'#f4b545':'#dcfa72'):(p.keeper?'#ec725b':'#558cff');let dark=home?'#71913c':'#304eae';ctx.fillStyle=dark;ctx.beginPath();ctx.ellipse(0,7*scale,r*.78,r*.48,0,0,TAU);ctx.fill();ctx.fillStyle=shirt;ctx.beginPath();ctx.ellipse(0,0,r*.78,r*.97,0,0,TAU);ctx.fill();ctx.fillStyle=home?'#ffffff65':'#ffffff53';ctx.fillRect(-r*.1,-r*.64,r*.2,r*1.2);ctx.fillStyle='#f2c9a1';ctx.beginPath();ctx.arc(0,-r*.8,r*.4,0,TAU);ctx.fill();ctx.fillStyle=home?'#23331a':'#182444';ctx.font=`900 ${Math.max(7,9*scale)}px system-ui`;ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(p.number,0,r*.17);ctx.restore();}
function drawBall(){let x=sx(ball.x),y=sy(ball.y),z=(ball.z||0)*scale,r=ball.r*scale;ctx.fillStyle='#07140c70';ctx.beginPath();ctx.ellipse(x+4*scale,sy(ball.y)+5*scale,r*1.25,r*.65,0,0,TAU);ctx.fill();ctx.save();ctx.translate(x,y-z);ctx.rotate(performance.now()*.0015);ctx.fillStyle='#fffef0';ctx.beginPath();ctx.arc(0,0,r,0,TAU);ctx.fill();ctx.fillStyle='#1b2b26';for(let i=0;i<5;i++){let a=i*TAU/5;ctx.beginPath();ctx.arc(Math.cos(a)*r*.58,Math.sin(a)*r*.58,r*.22,0,TAU);ctx.fill()}ctx.restore();}
function render(){ctx.setTransform(dpr,0,0,dpr,0,0);drawPitch();for(const p of players.slice().sort((a,b)=>a.y-b.y))drawPlayer(p);drawBall();if(!playing){ctx.fillStyle='#fff';}}
function loop(now){if(!playing)return;let dt=Math.min(.035,(now-last)/1000||.016);last=now;if(!paused)gameUpdate(dt);render();raf=requestAnimationFrame(loop);}
// Analog stick: pointer capture keeps movement smooth when a thumb slides beyond the pad.
const joy=$('#joy'),knob=$('#knob');let joyPointer=null;function setJoy(e){let r=joy.getBoundingClientRect(),cx=r.left+r.width/2,cy=r.top+r.height/2,dx=e.clientX-cx,dy=e.clientY-cy,max=r.width*.34,len=hyp(dx,dy),ratio=Math.min(1,max/(len||1));input.x=dx/(max||1);input.y=dy/(max||1);let mag=hyp(input.x,input.y);if(mag>1){input.x/=mag;input.y/=mag}knob.style.left=`calc(50% + ${dx*ratio}px)`;knob.style.top=`calc(50% + ${dy*ratio}px)`;}
joy.addEventListener('pointerdown',e=>{e.preventDefault();joyPointer=e.pointerId;joy.setPointerCapture(e.pointerId);setJoy(e)});joy.addEventListener('pointermove',e=>{if(joyPointer===e.pointerId)setJoy(e)});function releaseJoy(e){if(joyPointer===e.pointerId){joyPointer=null;input.x=input.y=0;knob.style.left='50%';knob.style.top='50%'}}joy.addEventListener('pointerup',releaseJoy);joy.addEventListener('pointercancel',releaseJoy);
$('#passBtn').addEventListener('pointerdown',e=>{e.preventDefault();pass()});$('#shootBtn').addEventListener('pointerdown',e=>{e.preventDefault();if(!possession())return;input.shoot=true;input.charge=.12;$('#power').classList.add('on')});function releaseShoot(){if(input.shoot){input.shoot=false;shoot()}}$('#shootBtn').addEventListener('pointerup',releaseShoot);$('#shootBtn').addEventListener('pointercancel',releaseShoot);$('#shootBtn').addEventListener('pointerleave',e=>{if(e.buttons===0)releaseShoot()});
const sprintBtn=$('#sprintBtn');function sprintDown(e){e.preventDefault();if(!possession())changeControl();else input.sprint=true}function sprintUp(){input.sprint=false} sprintBtn.addEventListener('pointerdown',sprintDown);sprintBtn.addEventListener('pointerup',sprintUp);sprintBtn.addEventListener('pointercancel',sprintUp);sprintBtn.addEventListener('pointerleave',e=>{if(e.buttons===0)sprintUp()});
function syncControlLabel(){let has=possession()?.side===0;$('#sprintLabel').textContent=has?'SPRINT':'SWITCH';$('#sprintCaption').textContent=has?'HOLD':'TAP';}
setInterval(syncControlLabel,150);
document.querySelectorAll('.mode').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('.mode').forEach(x=>x.classList.remove('selected'));b.classList.add('selected')}));$('#playBtn').addEventListener('click',startGame);$('#rematchBtn').addEventListener('click',startGame);
$('#pauseBtn').addEventListener('click',()=>{if(!playing)return;paused=!paused;$('#pauseMark').classList.toggle('hide',!paused);$('#pauseBtn').textContent=paused?'▶':'Ⅱ';if(!paused)last=performance.now()});$('#soundBtn').addEventListener('click',()=>{soundOn=!soundOn;$('#soundBtn').textContent=soundOn?'♫':'♩';if(soundOn)sound('pass')});
window.addEventListener('keydown',e=>{let k=e.key.toLowerCase();if(['arrowup','arrowdown','arrowleft','arrowright',' '].includes(k))e.preventDefault();if(k==='w'||k==='arrowup')input.y=-1;if(k==='s'||k==='arrowdown')input.y=1;if(k==='a'||k==='arrowleft')input.x=-1;if(k==='d'||k==='arrowright')input.x=1;if(k==='shift')input.sprint=true;if(k===' '){input.shoot=true;input.charge=Math.max(.12,input.charge)}});window.addEventListener('keyup',e=>{let k=e.key.toLowerCase();if(k==='w'||k==='arrowup'||k==='s'||k==='arrowdown')input.y=0;if(k==='a'||k==='arrowleft'||k==='d'||k==='arrowright')input.x=0;if(k==='shift')input.sprint=false;if(k===' '){input.shoot=false;shoot()}});window.addEventListener('blur',()=>{input.x=input.y=0;input.sprint=false;if(input.shoot)releaseShoot()});
// Paint an attractive live pitch behind the setup card too.
players=[...makeTeam(0,5),...makeTeam(1,5)];ball={x:1200,y:500,vx:0,vy:0,r:11,z:0};render();
})();
</script>
</body>
</html>

