Index: index.html
===================================================================
--- index.html
+++ index.html
@@ -35,4 +35,24 @@
 <div class="overlay" id="startScreen"><div class="panel"><div class="eyebrow">A LITTLE GAME OF FOOTBALL</div><h1>OWN THE<br><em>TOUCHLINE.</em></h1><p>Find your space. Pick your pass. Make the moment count. Two minutes, one pitch, your call.</p><div class="mode-label">PICK YOUR SIDES</div><div class="modes"><button class="mode selected" data-mode="5"><strong>5 v 5</strong><small>Quick &amp; nimble</small></button><button class="mode" data-mode="7"><strong>7 v 7</strong><small>More room to play</small></button></div><button class="play" id="playBtn">KICK OFF <span>→</span></button><div class="help">MOVE with the stick · PASS into space · HOLD SHOOT to charge<br>SPRINT while you have the ball · SWITCH when defending</div></div></div>
 <div class="overlay hide" id="endScreen"><div class="panel"><div class="eyebrow">FULL TIME</div><h1 id="resultTitle">WHAT A<br><em>GAME.</em></h1><p id="resultText">The whistle blows. That's football.</p><button class="play" id="rematchBtn">PLAY AGAIN <span>↻</span></button></div></div>
 <div class="rotate"><div><span class="rotate-mark">↻</span><strong>ROTATE TO PLAY</strong><p>Touchline is best enjoyed in landscape.</p></div></div>
 <script>
+(()=>{'use strict';
+const canvas=document.querySelector('#game'),ctx=canvas.getContext('2d',{alpha:false}),$=s=>document.querySelector(s),W=2400,H=1000,TAU=Math.PI*2;
+let cw=0,ch=0,dpr=1,scale=1,cameraX=1200,players=[],ball,selectedMode=5,selectedId=null,score=[0,0],timeLeft=120,playing=false,paused=false,finished=false,last=0,raf=0,soundOn=true,audio;
+const input={x:0,y:0,sprint:false,shoot:false,charge:0},clamp=(n,a,b)=>Math.max(a,Math.min(b,n)),hyp=Math.hypot;
+function resize(){cw=innerWidth;ch=innerHeight;dpr=Math.min(devicePixelRatio||1,2);canvas.width=cw*dpr;canvas.height=ch*dpr;canvas.style.width=cw+'px';canvas.style.height=ch+'px';ctx.setTransform(dpr,0,0,dpr,0,0);scale=ch/1000}addEventListener('resize',resize);resize();
+function team(side,n){let out=[],field=n-1,cols=Math.ceil(field/2);for(let i=0;i<n;i++){let keeper=i===0,row=i-1;out.push({id:side+'-'+i,side,keeper,x:side===0?(keeper?95:410+Math.floor(row/cols)*300):(keeper?2305:1990-Math.floor(row/cols)*300),y:keeper?500:220+(row%cols)*(560/Math.max(1,cols-1)),vx:0,vy:0,r:keeper?21:20,homeX:side===0?(keeper?95:410+Math.floor(row/cols)*300):(keeper?2305:1990-Math.floor(row/cols)*300),homeY:keeper?500:220+(row%cols)*(560/Math.max(1,cols-1)),number:keeper?'1':String(i+1),facing:side===0?0:Math.PI,stun:0})}return out}
+function nearest(side,x,y,excludeKeeper=false){let best=null,dmin=Infinity;for(let p of players){if(p.side!==side||(excludeKeeper&&p.keeper))continue;let d=(p.x-x)**2+(p.y-y)**2;if(d<dmin)dmin=d,best=p}return best}
+function owner(){return ball.owner?players.find(p=>p.id===ball.owner):null}
+function say(s){let e=$('#toast');e.textContent=s;e.classList.add('show');clearTimeout(say.t);say.t=setTimeout(()=>e.classList.remove('show'),1250)}
+function sound(type){if(!soundOn)return;try{audio??=new(window.AudioContext||webkitAudioContext)();if(audio.state==='suspended')audio.resume();let t=audio.currentTime,o=audio.createOscillator(),g=audio.createGain();o.connect(g);g.connect(audio.destination);o.type=type==='whistle'?'sine':'triangle';o.frequency.setValueAtTime(type==='whistle'?880:type==='goal'?220:type==='pass'?390:160,t);o.frequency.exponentialRampToValueAtTime(type==='goal'?660:(type==='whistle'?650:90),t+.18);g.gain.setValueAtTime(type==='goal'?.1:.05,t);g.gain.exponentialRampToValueAtTime(.001,t+.28);o.start(t);o.stop(t+.3)}catch{}}
+function refresh(){ $('#homeScore').textContent=score[0];$('#awayScore').textContent=score[1];$('#clock').textContent=String(Math.floor(timeLeft/60)).padStart(2,'0')+':'+String(Math.ceil(timeLeft%60)).padStart(2,'0') }
+function start(){selectedMode=+document.querySelector('.mode.selected').dataset.mode;players=[...team(0,selectedMode),...team(1,selectedMode)];score=[0,0];timeLeft=120;ball={x:1200,y:500,vx:0,vy:0,r:11,z:0,vz:0,owner:null};cameraX=1200;playing=true;paused=finished=false;input.charge=0;$('#startScreen').classList.add('hide');$('#endScreen').classList.add('hide');$('#pauseMark').classList.add('hide');$('#pauseBtn').textContent='Ⅱ';say('KICK OFF');sound('whistle');last=performance.now();cancelAnimationFrame(raf);raf=requestAnimationFrame(loop)}
+function resetPositions(){players.forEach(p=>{p.x=p.homeX;p.y=p.homeY;p.vx=p.vy=0;p.stun=0});ball={x:1200,y:500,vx:0,vy:0,r:11,z:0,vz:0,owner:null}}
+function kick(p,kind,power=1){if(!p)return;let dx,dy,speed;if(kind==='shoot'){dx=p.side===0?1:-1;dy=clamp((ball.y-500)/500,-.36,.36)+input.y*.23;speed=690+power*580}else{let mates=players.filter(t=>t.side===p.side&&t!==p&&!t.keeper),ax=input.x||(p.side===0?1:-1),ay=input.y;let target=mates.sort((a,b)=>{let da=hyp(a.x-p.x,a.y-p.y),db=hyp(b.x-p.x,b.y-p.y),aa=((a.x-p.x)*ax+(a.y-p.y)*ay)/(da||1),ab=((b.x-p.x)*ax+(b.y-p.y)*ay)/(db||1);return da*(1-aa*.65)-db*(1-ab*.65)})[0];dx=target?target.x-p.x:(p.side===0?1:-1);dy=target?target.y-p.y:0;let l=hyp(dx,dy)||1;dx/=l;dy/=l;speed=510}if(kind==='shoot'){let l=hyp(dx,dy)||1;dx/=l;dy/=l}ball.owner=null;ball.x=p.x+dx*28;ball.y=p.y+dy*28;ball.vx=dx*speed+p.vx*.25;ball.vy=dy*speed+p.vy*.25;ball.z=kind==='shoot'?9:3;ball.vz=kind==='shoot'?120:20;p.stun=.16;sound(kind==='shoot'?'kick':'pass');if(kind==='pass')say('PLAYED INTO SPACE')}
+function shoot(){if(!owner())return;kick(owner(),'shoot',input.charge);input.charge=0;$('#power').classList.remove('on')}
